/* Base icon styles */
.gel-icon,
.gel-logo,
.gel-pictogram {
  display: inline-block;
  width: 1em;
  height: 1em;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  vertical-align: middle;
  background-color: currentcolor;
  mask-image:url('');
  mask-size: contain;
  mask-repeat: no-repeat;
  mask-position: center;
}

/* Default icon size (24px) */
.gel-icon {
  width: 24px;
  height: 24px;
}

/* Default logo size (auto width, 24px height) */
.gel-logo {
  width: auto;
  height: 24px;
}

/* Default pictogram size (78px) */
.gel-pictogram {
  width: 78px;
  height: 78px;
}

/* Size modifiers */
.gel-icon-xs,
.gel-logo-xs,
.gel-pictogram-xs {
  width: 16px;
  height: 16px;
}

.gel-icon-sm,
.gel-logo-sm,
.gel-pictogram-sm {
  width: 20px;
  height: 20px;
}

.gel-icon-md,
.gel-logo-md,
.gel-pictogram-md {
  width: 24px;
  height: 24px;
}

.gel-icon-lg,
.gel-logo-lg,
.gel-pictogram-lg {
  width: 32px;
  height: 32px;
}

.gel-icon-xl,
.gel-logo-xl,
.gel-pictogram-xl {
  width: 48px;
  height: 48px;
}

.gel-icon-2xl,
.gel-logo-2xl,
.gel-pictogram-2xl {
  width: 64px;
  height: 64px;
}

/* Accessibility helper - hide from screen readers if decorative */
.gel-icon[aria-hidden="true"],
.gel-logo[aria-hidden="true"],
.gel-pictogram[aria-hidden="true"] {
  pointer-events: none;
}



